import { test } from "node:test";
import assert from "node:assert/strict";

import { normalizeTheme, axisStyle, withAlpha } from "../static/theme-data.js";

test("normalizeTheme defaults to light", () => {
  assert.equal(normalizeTheme(null), "light");
  assert.equal(normalizeTheme("purple"), "light");
  assert.equal(normalizeTheme("dark"), "dark");
  assert.equal(normalizeTheme("system"), "system");
});

test("axisStyle sets every canvas color explicitly", () => {
  const a = axisStyle({ axis: "#a7b0bc", grid: "#2f343c" }, { size: 40 });
  assert.equal(a.stroke, "#a7b0bc");
  assert.deepEqual(a.grid, { stroke: "#2f343c", width: 1 });
  assert.deepEqual(a.ticks, { stroke: "#2f343c", width: 1 });
  assert.equal(a.size, 40);
  assert.equal(axisStyle({ axis: "x", grid: "y" }, { grid: { show: false } }).grid.show, false);
});

test("withAlpha appends hex alpha to #rrggbb only", () => {
  assert.equal(withAlpha("#c2410c", 0.2), "#c2410c33");
  assert.equal(withAlpha("#C2410C", 1), "#C2410Cff");
  assert.equal(withAlpha("rgb(1 2 3)", 0.5), "rgb(1 2 3)");
});
